      "tipo": "DrawCalls",
      "causa_raiz": "O volume de Draw Calls atingiu o pico de 20.492 chamadas (limite orçado de 2.579), gerando sobrecarga direta no pipeline de renderização e elevando o tempo de GPU para até 43.89ms. Isso ocorre devido à renderização individualizada de milhares de objetos sem agrupamento por GPU Instancing, Static/Dynamic Batching ou atlasing de materiais.",
      "codigo_refatorado": "using UnityEngine;

public class InstancedObjectRenderer : MonoBehaviour
{
    [SerializeField] private Mesh targetMesh;
    [SerializeField] private Material targetMaterial;
    [SerializeField] private int totalInstances = 1000;
    [SerializeField] private float areaRadius = 50f;

    private Matrix4x4[][] batches;
    private MaterialPropertyBlock propertyBlock;
    private const int BATCH_SIZE = 1023;

    private void Awake()
    {
        propertyBlock = new MaterialPropertyBlock();
        InitializeBatches();
    }

    private void InitializeBatches()
    {
        int batchCount = Mathf.CeilToInt((float)totalInstances / BATCH_SIZE);
        batches = new Matrix4x4[batchCount][];

        int remaining = totalInstances;
        for (int i = 0; i < batchCount; i++)
        {
            int currentSize = Mathf.Min(remaining, BATCH_SIZE);
            batches[i] = new Matrix4x4[currentSize];
            for (int j = 0; j < currentSize; j++)
            {
                Vector3 position = Random.insideUnitSphere * areaRadius;
                position.y = 0f;
                Quaternion rotation = Quaternion.Euler(0f, Random.Range(0f, 360f), 0f);
                Vector3 scale = Vector3.one * Random.Range(0.8f, 1.2f);
                batches[i][j] = Matrix4x4.TRS(position, rotation, scale);
            }
            remaining -= currentSize;
        }
    }

    private void Update()
    {
        if (targetMesh == null || targetMaterial == null) return;

        for (int i = 0; i < batches.Length; i++)
        {
            Graphics.DrawMeshInstanced(
                targetMesh,
                0,
                targetMaterial,
                batches[i],
                batches[i].Length,
                propertyBlock
            );
        }
    }
}",
      "explicacao_didatica": "Imagine o Draw Call como um garçom levando pedidos da cozinha (CPU) para a mesa (GPU). Fazer 20.000 pedidos individuais obriga o garçom a fazer 20.000 viagens, parando tudo. O código refatorado usa GPU Instancing ('Graphics.DrawMeshInstanced'), agrupando até 1.023 objetos idênticos em uma única bandeja por viagem. Isso reduz milhares de Draw Calls para apenas uma fração, permitindo que a GTX 1650 processe a cena dentro do limite de 16.7ms (60 FPS)."
    }
  ],
  "dicas_level_design": "1. Habilite a opção 'Enable GPU Instancing' em todos os materiais aplicados a objetos repetidos (como vegetação, escombros, rochas e projéteis).
2. Marque elementos de cenário que não se movem como 'Batching Static' e certifique-se de que 'Static Batching' está ativo nas Player Settings.
3. Implemente LOD (Level of Detail) Groups e configure distâncias agressivas de Culling via Layer Cull Distances na câmera principal para não renderizar objetos pequenos a longas distâncias.
4. Crie Atlas de Texturas agrupando múltiplos materiais em um único material/shader compartilhado, eliminando a quebra de batches no renderizador.
5. Configure Occlusion Culling na cena estática para que objetos ocultados atrás de paredes ou montanhas nem sequer enviem comandos de desenho para a GPU."
}

